<section class="section" dir="rtl"><div class="container container--md"><header class="section__head"><div><span class="eyebrow">ثبت‌نام‌های شما</span><h1><?= $history?'سوابق و پیگیری پرداخت':'کدام ثبت‌نام را ادامه می‌دهید؟' ?></h1><p><?= $history?'هر ثبت‌نام صفحه پرداخت و پیگیری جداگانه دارد.':'فقط ثبت‌نام‌های در حال پیگیری در این بخش نمایش داده می‌شوند.' ?></p></div><a class="btn btn--secondary" href="<?= $history?'/payments':'/payments/history' ?>"><?= $history?'پرداخت‌های فعال':'سوابق پرداخت' ?></a></header>
<?php if($notice): ?><p class="alert" role="status"><?= e($notice) ?></p><?php endif; ?>
<div class="checkout-orders"><?php foreach($contexts as $context): ?><a class="checkout-order" href="/payments/<?= e($context['type']) ?>/<?= e($context['id']) ?>"><span class="checkout-item-icon"><?= icon($context['type']==='circle'?'users':'book-open') ?></span><div><h2><?= e($context['item']['title']) ?></h2><small><?= e(['requested'=>'پذیرش در حال بررسی','approved'=>'پذیرش تأیید شده','rejected'=>'پذیرش تأیید نشد','canceled'=>'لغوشده','attended'=>'حضور ثبت شده'][$context['request']['status']]??'پیگیری ثبت‌نام') ?> · <?= number_format($context['total']) ?> تومان</small></div><?= icon('arrow-left') ?></a><?php endforeach; ?></div>
<?php if(!$contexts): ?><div class="user-panel"><h2><?= $history?'هنوز ثبت‌نامی ندارید':'پرداخت فعال دیگری ندارید' ?></h2><a class="btn btn--primary" href="/courses">مشاهده دوره‌ها</a><a class="btn btn--secondary" href="/events">حلقه درمانگران</a></div><?php endif; ?>
<?php if($history): ?><nav class="cluster mt-6"><?php if($page>1): ?><a class="btn btn--secondary" href="?page=<?= $page-1 ?>">قبلی</a><?php endif; ?><?php if($hasMore): ?><a class="btn btn--secondary" href="?page=<?= $page+1 ?>">بعدی</a><?php endif; ?></nav><?php endif; ?></div></section>
